// what the database stores, mapped to the pack's file names
const ALIAS: Record<string, string> = {
  zoom: 'zoom-classic', zoom_meetings: 'zoom-classic',
  google_calendar: 'google-calendar', gcal: 'google-calendar', calendar: 'google-calendar',
  meet: 'google-meet', google_meet: 'google-meet', teams: 'microsoft-teams', microsoft_teams: 'microsoft-teams',
  ms_teams: 'microsoft-teams', o365: 'outlook', office365: 'outlook', outlook_mail: 'outlook',
  whatsapp_business: 'whatsapp', wa: 'whatsapp', call: 'phone-call', calls: 'phone-call', phone: 'phone-call',
  text: 'sms', message: 'sms', sfdc: 'salesforce', linkedin_sales_navigator: 'linkedin',
  li: 'linkedin', fireflies_ai: 'fireflies',
  zoho: 'zoho-crm', zoho_crm: 'zoho-crm', dynamics: 'microsoft-dynamics-365', dynamics365: 'microsoft-dynamics-365',
  ms_dynamics: 'microsoft-dynamics-365', ringcentral: 'phone-call', dialpad: 'phone-call',
}

export const SOURCE_LABEL: Record<string, string> = {
  gmail: 'Gmail', outlook: 'Outlook', slack: 'Slack', 'microsoft-teams': 'Microsoft Teams', whatsapp: 'WhatsApp',
  zoom: 'Zoom', 'zoom-classic': 'Zoom', 'google-meet': 'Google Meet', 'google-calendar': 'Google Calendar',
  fireflies: 'Fireflies', gong: 'Gong', 'phone-call': 'Calls', sms: 'SMS', hubspot: 'HubSpot',
  salesforce: 'Salesforce', zendesk: 'Zendesk', notion: 'Notion', linkedin: 'LinkedIn',
  'zoho-crm': 'Zoho CRM', pipedrive: 'Pipedrive', stripe: 'Stripe', 'microsoft-dynamics-365': 'Dynamics 365',
  attio: 'Attio', aircall: 'Aircall', justcall: 'JustCall', twilio: 'Twilio', apollo: 'Apollo',
  salesloft: 'Salesloft', telegram: 'Telegram', calendly: 'Calendly', fathom: 'Fathom', intercom: 'Intercom',
}

/** The pack's key for whatever the detector stored ("gcal" -> "google-calendar"). */
export function sourceKey(raw?: string | null): string {
  const k = String(raw ?? '').trim().toLowerCase().replace(/[\s_]+/g, '_')
  if (ALIAS[k]) return ALIAS[k]   // aliases win, so "zoom" can point at the camera badge rather than the Z tile
  if (SOURCE_SVG[k]) return k
  const dashed = k.replace(/_/g, '-')
  return SOURCE_SVG[dashed] ? dashed : ''
}

/** The brand name to read out, for the label and for screen readers. */
export function sourceLabel(raw?: string | null): string {
  const key = sourceKey(raw)
  if (key) return SOURCE_LABEL[key] ?? key
  const s = String(raw ?? '').trim()
  return s ? s[0].toUpperCase() + s.slice(1) : 'Source'
}
